real_t algorithm_reduce_sum(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t acc = 0.0;
    for (int nl = 0; nl < iterations; ++nl) {
        real_t s = 0.0;
        Index_type i = 0;

#if defined(__riscv_vector) && defined(__has_include)
#  if __has_include(<riscv_vector.h>)
#    include <riscv_vector.h>
#    if defined(real_t) /* keep preprocessor quiet if real_t is a macro */
#    endif
        {
            const real_t *px = x;
            size_t n = (size_t)LEN_1D;

            if (sizeof(real_t) == sizeof(double)) {
#if defined(__riscv_v_elen) && (__riscv_v_elen >= 64)
                const double *p64 = (const double *)px;
                while (n > 0) {
                    size_t vl = __riscv_vsetvl_e64m4(n);
                    vfloat64m4_t vx = __riscv_vle64_v_f64m4(p64 + i, vl);
                    vfloat64m1_t vs = __riscv_vfmv_v_f_f64m1(0.0, 1);
                    vfloat64m1_t vr = __riscv_vfredusum_vs_f64m4_f64m1(vs, vx, vs, vl);
                    s += (real_t)__riscv_vfmv_f_s_f64m1_f64(vr);
                    i += (Index_type)vl;
                    n -= vl;
                }
#endif
            } else if (sizeof(real_t) == sizeof(float)) {
                const float *p32 = (const float *)px;
                while (n > 0) {
                    size_t vl = __riscv_vsetvl_e32m4(n);
                    vfloat32m4_t vx = __riscv_vle32_v_f32m4(p32 + i, vl);
                    vfloat32m1_t vs = __riscv_vfmv_v_f_f32m1(0.0f, 1);
                    vfloat32m1_t vr = __riscv_vfredusum_vs_f32m4_f32m1(vs, vx, vs, vl);
                    s += (real_t)__riscv_vfmv_f_s_f32m1_f32(vr);
                    i += (Index_type)vl;
                    n -= vl;
                }
            }
        }
#  endif
#endif

        for (; i < LEN_1D; ++i) {
            s += x[i];
        }

        acc += s;
        dummy(x, NULL, NULL, NULL, NULL, s);
    }
    y[0] = acc;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

