real_t apps_del_dot_vec_2d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t half = 0.5f, ptiny = 1.0e-20f;
    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t xi  = half * ( apps_x1[i]  + apps_x2[i]  - apps_x3[i]  - apps_x4[i]  );
            real_t xj  = half * ( apps_x2[i]  + apps_x3[i]  - apps_x4[i]  - apps_x1[i]  );
            real_t yi  = half * ( apps_y1[i]  + apps_y2[i]  - apps_y3[i]  - apps_y4[i]  );
            real_t yj  = half * ( apps_y2[i]  + apps_y3[i]  - apps_y4[i]  - apps_y1[i]  );
            real_t fxi = half * ( apps_fx1[i] + apps_fx2[i] - apps_fx3[i] - apps_fx4[i] );
            real_t fxj = half * ( apps_fx2[i] + apps_fx3[i] - apps_fx4[i] - apps_fx1[i] );
            real_t fyi = half * ( apps_fy1[i] + apps_fy2[i] - apps_fy3[i] - apps_fy4[i] );
            real_t fyj = half * ( apps_fy2[i] + apps_fy3[i] - apps_fy4[i] - apps_fy1[i] );
            real_t rarea = 1.0f / ( xi * yj - xj * yi + ptiny );
            real_t dfxdx  = rarea * ( fxi * yj - fxj * yi );
            real_t dfydy  = rarea * ( fyj * xi - fyi * xj );
            real_t affine = ( apps_fy1[i] + apps_fy2[i] + apps_fy3[i] + apps_fy4[i] ) /
                            ( apps_y1[i]  + apps_y2[i]  + apps_y3[i]  + apps_y4[i]  );
            apps_div[i] = dfxdx + dfydy + affine;
        }
        dummy(apps_div, NULL, NULL, NULL, NULL, ptiny);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

real_t apps_energy(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t rho0 = 1.0f, e_cut = 1.0e-7f, emin = -1.0e15f;
    for (int nl = 0; nl < iterations / 8 + 1; nl++) {
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_e_new[i] = apps_e_old[i] - 0.5f * apps_delvc[i] *
                            (apps_p_old[i] + apps_q_old[i]) + 0.5f * apps_work[i];
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            if (apps_delvc[i] > 0.0f) {
                apps_q_new[i] = 0.0f;
            } else {
                real_t vhalf = 1.0f / (1.0f + apps_compHalfStep[i]);
                real_t ssc = ( apps_pbvc[i] * apps_e_new[i] +
                               vhalf * vhalf * apps_bvc[i] * apps_pHalfStep[i] ) / rho0;
                if (ssc <= 1.111111e-36f) ssc = 3.333333e-18f;
                else                      ssc = sqrtf(ssc);
                apps_q_new[i] = ssc * apps_ql_old[i] + apps_qq_old[i];
            }
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_e_new[i] += 0.5f * apps_delvc[i] *
                             ( 3.0f*(apps_p_old[i] + apps_q_old[i]) -
                               4.0f*(apps_pHalfStep[i] + apps_q_new[i]) );
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_e_new[i] += 0.5f * apps_work[i];
            if (ABS(apps_e_new[i]) < e_cut) apps_e_new[i] = 0.0f;
            if (apps_e_new[i] < emin)        apps_e_new[i] = emin;
        }
        dummy(apps_e_new, apps_q_new, NULL, NULL, NULL, e_cut);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

real_t apps_fir(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const Index_type coefflen = APPS_COEFFLEN;
    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            const real_t *coeffp = apps_coeff;
            const real_t *inp = apps_in + i;
            real_t s = 0.0f;

#if defined(__riscv_vector) && defined(__has_include)
#  if __has_include(<riscv_vector.h>)
#    include <riscv_vector.h>
            Index_type j = 0;
            for (; j < coefflen; ) {
                size_t vl = __riscv_vsetvl_e32m1((size_t)(coefflen - j));
                vfloat32m1_t vcoeff = __riscv_vle32_v_f32m1((const float *)(coeffp + j), vl);
                vfloat32m1_t vin = __riscv_vle32_v_f32m1((const float *)(inp + j), vl);
                vfloat32m1_t vacc = __riscv_vfmul_vv_f32m1(vcoeff, vin, vl);
                vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, vl);
                vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(vzero, vacc, vzero, vl);
                s += __riscv_vfmv_f_s_f32m1_f32(vred);
                j += (Index_type)vl;
            }
#  else
            for (Index_type j = 0; j < coefflen; ++j) {
                s += coeffp[j] * inp[j];
            }
#  endif
#else
            for (Index_type j = 0; j < coefflen; ++j) {
                s += coeffp[j] * inp[j];
            }
#endif

            apps_out[i] = s;
        }
        dummy(apps_out, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

real_t apps_ltimes_noview(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type num_d = LTIMES_NUM_D, num_m = LTIMES_NUM_M;
    Index_type num_g = LTIMES_NUM_G, num_z = LTIMES_NUM_Z;

    for (int nl = 0; nl < iterations; nl++) {
        for (Index_type z = 0; z < num_z; ++z) {
            const Index_type z_phi_base = z * num_m * num_g;
            const Index_type z_psi_base = z * num_d * num_g;

            for (Index_type g = 0; g < num_g; ++g) {
                const Index_type phi_base = z_phi_base + g * num_m;
                const Index_type psi_base = z_psi_base + g * num_d;
                const real_t *psi_ptr = &lt_psidat[psi_base];

                for (Index_type m = 0; m < num_m; ++m) {
                    const real_t *ell_ptr = &lt_elldat[m * num_d];
                    real_t sum = lt_phidat[phi_base + m];

                    Index_type dd = 0;
                    for (; dd + 3 < num_d; dd += 4) {
                        sum += ell_ptr[dd] * psi_ptr[dd];
                        sum += ell_ptr[dd + 1] * psi_ptr[dd + 1];
                        sum += ell_ptr[dd + 2] * psi_ptr[dd + 2];
                        sum += ell_ptr[dd + 3] * psi_ptr[dd + 3];
                    }
                    for (; dd < num_d; ++dd) {
                        sum += ell_ptr[dd] * psi_ptr[dd];
                    }

                    lt_phidat[phi_base + m] = sum;
                }
            }
        }
        dummy(lt_phidat, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

