real_t apps_nodal_accumulation_3d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const int outer = iterations / 4 + 1;

    real_t *x0 = apps_x0;
    real_t *x1 = apps_x1;
    real_t *x2 = apps_x2;
    real_t *x3 = apps_x3;
    real_t *x4 = apps_x4;
    real_t *x5 = apps_x5;
    real_t *x6 = apps_x6;
    real_t *x7 = apps_x7;
    real_t *vol = apps_vol;

    for (int nl = 0; nl < outer; nl++) {
        Index_type i = 0;

        for (; i + 3 < APPS_N1D; i += 4) {
            real_t v0 = 0.125f * vol[i + 0];
            real_t v1 = 0.125f * vol[i + 1];
            real_t v2 = 0.125f * vol[i + 2];
            real_t v3 = 0.125f * vol[i + 3];

            x0[i + 0] += v0; x1[i + 0] += v0; x2[i + 0] += v0; x3[i + 0] += v0;
            x4[i + 0] += v0; x5[i + 0] += v0; x6[i + 0] += v0; x7[i + 0] += v0;

            x0[i + 1] += v1; x1[i + 1] += v1; x2[i + 1] += v1; x3[i + 1] += v1;
            x4[i + 1] += v1; x5[i + 1] += v1; x6[i + 1] += v1; x7[i + 1] += v1;

            x0[i + 2] += v2; x1[i + 2] += v2; x2[i + 2] += v2; x3[i + 2] += v2;
            x4[i + 2] += v2; x5[i + 2] += v2; x6[i + 2] += v2; x7[i + 2] += v2;

            x0[i + 3] += v3; x1[i + 3] += v3; x2[i + 3] += v3; x3[i + 3] += v3;
            x4[i + 3] += v3; x5[i + 3] += v3; x6[i + 3] += v3; x7[i + 3] += v3;
        }

        for (; i < APPS_N1D; ++i) {
            real_t val = 0.125f * vol[i];
            x0[i] += val; x1[i] += val;
            x2[i] += val; x3[i] += val;
            x4[i] += val; x5[i] += val;
            x6[i] += val; x7[i] += val;
        }

        dummy(apps_x0, apps_x7, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

real_t apps_pressure(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const real_t cls = 1.0f;
    const real_t p_cut = 1.0e-7f;
    const real_t pmin = 0.0f;
    const real_t eosvmax = 1.0e9f;

    for (int nl = 0; nl < iterations / 4 + 1; ++nl) {
#if defined(__riscv_vector) && defined(__has_include)
#  if __has_include(<riscv_vector.h>)
#    include <riscv_vector.h>
        {
            Index_type i = 0;
            for (; i < APPS_N1D; ) {
                size_t vl = __riscv_vsetvl_e32m8((size_t)(APPS_N1D - i));
                vfloat32m8_t vcomp = __riscv_vle32_v_f32m8(&apps_compression[i], vl);
                vfloat32m8_t vbvc = __riscv_vfadd_vf_f32m8(vcomp, 1.0f, vl);
                vbvc = __riscv_vfmul_vf_f32m8(vbvc, cls, vl);
                __riscv_vse32_v_f32m8(&apps_bvc[i], vbvc, vl);
                i += (Index_type)vl;
            }
        }
        {
            Index_type i = 0;
            for (; i < APPS_N1D; ) {
                size_t vl = __riscv_vsetvl_e32m8((size_t)(APPS_N1D - i));

                vfloat32m8_t vbvc  = __riscv_vle32_v_f32m8(&apps_bvc[i], vl);
                vfloat32m8_t veold = __riscv_vle32_v_f32m8(&apps_e_old[i], vl);
                vfloat32m8_t vvnew = __riscv_vle32_v_f32m8(&apps_vnewc[i], vl);

                vfloat32m8_t vp = __riscv_vfmul_vv_f32m8(vbvc, veold, vl);

                vfloat32m8_t vabs = __riscv_vfsgnjx_vv_f32m8(vp, vp, vl);
                vbool4_t m_small = __riscv_vmflt_vf_f32m8_b4(vabs, p_cut, vl);
                vp = __riscv_vfmerge_vfm_f32m8(vp, 0.0f, m_small, vl);

                vbool4_t m_eos = __riscv_vmfge_vf_f32m8_b4(vvnew, eosvmax, vl);
                vp = __riscv_vfmerge_vfm_f32m8(vp, 0.0f, m_eos, vl);

                vbool4_t m_pmin = __riscv_vmflt_vf_f32m8_b4(vp, pmin, vl);
                vp = __riscv_vfmerge_vfm_f32m8(vp, pmin, m_pmin, vl);

                __riscv_vse32_v_f32m8(&apps_p_new[i], vp, vl);
                i += (Index_type)vl;
            }
        }
#  else
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_bvc[i] = cls * (apps_compression[i] + 1.0f);
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t p = apps_bvc[i] * apps_e_old[i];
