real_t apps_vol3d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const real_t vnormq = 0.0833333333333f;

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        Index_type i = 0;

#define APPS_VOL3D_CALC_ONE(ii) do { \
            real_t x71 = apps_x7[(ii)] - apps_x1[(ii)], x72 = apps_x7[(ii)] - apps_x2[(ii)], x74 = apps_x7[(ii)] - apps_x4[(ii)]; \
            real_t x30 = apps_x3[(ii)] - apps_x0[(ii)], x50 = apps_x5[(ii)] - apps_x0[(ii)], x60 = apps_x6[(ii)] - apps_x0[(ii)]; \
            real_t y71 = apps_y7[(ii)] - apps_y1[(ii)], y72 = apps_y7[(ii)] - apps_y2[(ii)], y74 = apps_y7[(ii)] - apps_y4[(ii)]; \
            real_t y30 = apps_y3[(ii)] - apps_y0[(ii)], y50 = apps_y5[(ii)] - apps_y0[(ii)], y60 = apps_y6[(ii)] - apps_y0[(ii)]; \
            real_t z71 = apps_z7[(ii)] - apps_z1[(ii)], z72 = apps_z7[(ii)] - apps_z2[(ii)], z74 = apps_z7[(ii)] - apps_z4[(ii)]; \
            real_t z30 = apps_z3[(ii)] - apps_z0[(ii)], z50 = apps_z5[(ii)] - apps_z0[(ii)], z60 = apps_z6[(ii)] - apps_z0[(ii)]; \
            real_t xps = x71 + x60, yps = y71 + y60, zps = z71 + z60; \
            real_t cyz = y72*z30 - z72*y30, czx = z72*x30 - x72*z30, cxy = x72*y30 - y72*x30; \
            real_t v = xps*cyz + yps*czx + zps*cxy; \
            xps = x72 + x50; yps = y72 + y50; zps = z72 + z50; \
            cyz = y74*z60 - z74*y60; czx = z74*x60 - x74*z60; cxy = x74*y60 - y74*x60; \
            v += xps*cyz + yps*czx + zps*cxy; \
            xps = x74 + x30; yps = y74 + y30; zps = z74 + z30; \
            cyz = y71*z50 - z71*y50; czx = z71*x50 - x71*z50; cxy = x71*y50 - y71*x50; \
            v += xps*cyz + yps*czx + zps*cxy; \
            apps_vol[(ii)] = v * vnormq; \
        } while (0)

        for (; i + 3 < APPS_N1D; i += 4) {
            APPS_VOL3D_CALC_ONE(i);
            APPS_VOL3D_CALC_ONE(i + 1);
            APPS_VOL3D_CALC_ONE(i + 2);
            APPS_VOL3D_CALC_ONE(i + 3);
        }

        for (; i < APPS_N1D; ++i) {
            APPS_VOL3D_CALC_ONE(i);
        }

#undef APPS_VOL3D_CALC_ONE

        dummy(apps_vol, NULL, NULL, NULL, NULL, vnormq);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

