real_t basic_trap_int(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const real_t x0 = (real_t)0.0;
    const real_t h = (real_t)1.0 / (real_t)LEN_1D;
    const real_t yp = (real_t)1.0;
    const real_t ypoint = (real_t)1.0;
    const real_t dy = ypoint - yp;
    const real_t dy2 = dy * dy;
    const real_t half = (real_t)0.5;
    real_t acc = (real_t)0.0;

#if defined(BASIC_TRAP_INT_HAVE_RVV)
    for (int nl = 0; nl < iterations; nl++) {
        real_t sumx = (real_t)0.0;
        Index_type i = 0;

        if (sizeof(real_t) == sizeof(float)) {
            for (; i < LEN_1D; ) {
                const size_t vl = __riscv_vsetvl_e32m1((size_t)(LEN_1D - i));

                vuint32m1_t vidx = __riscv_vid_v_u32m1(vl);
                vfloat32m1_t vf_i = __riscv_vfcvt_f_xu_v_f32m1(vidx, vl);
                vf_i = __riscv_vfadd_vf_f32m1(vf_i, (float)i, vl);

                vfloat32m1_t xv = __riscv_vfmul_vf_f32m1(vf_i, (float)h, vl);
                xv = __riscv_vfadd_vf_f32m1(xv, (float)x0, vl);

                vfloat32m1_t d = __riscv_vfsub_vf_f32m1(xv, (float)half, vl);
                vfloat32m1_t denom = __riscv_vfmul_vv_f32m1(d, d, vl);
                denom = __riscv_vfadd_vf_f32m1(denom, (float)(dy2 + (real_t)1.0), vl);

                vfloat32m1_t root = __riscv_vfsqrt_v_f32m1(denom, vl);
                vfloat32m1_t vals = __riscv_vfrdiv_vf_f32m1(root, 1.0f, vl);

                vfloat32m1_t init = __riscv_vfmv_s_f_f32m1((float)sumx, vl);
                vfloat32m1_t red = __riscv_vfredosum_vs_f32m1_f32m1(vals, init, vl);
                sumx = (real_t)__riscv_vfmv_f_s_f32m1_f32(red);

                i += (Index_type)vl;
            }
        } else {
            for (; i < LEN_1D; ) {
                const size_t vl = __riscv_vsetvl_e64m1((size_t)(LEN_1D - i));

                vuint64m1_t vidx = __riscv_vid_v_u64m1(vl);
                vfloat64m1_t vf_i = __riscv_vfcvt_f_xu_v_f64m1(vidx, vl);
                vf_i = __riscv_vfadd_vf_f64m1(vf_i, (double)i, vl);

                vfloat64m1_t xv = __riscv_vfmul_vf_f64m1(vf_i, (double)h, vl);
                xv = __riscv_vfadd_vf_f64m1(xv, (double)x0, vl);

                vfloat64m1_t d = __riscv_vfsub_vf_f64m1(xv, (double)half, vl);
                vfloat64m1_t denom = __riscv_vfmul_vv_f64m1(d, d, vl);
                denom = __riscv_vfadd_vf_f64m1(denom, (double)(dy2 + (real_t)1.0), vl);

                vfloat64m1_t root = __riscv_vfsqrt_v_f64m1(denom, vl);
                vfloat64m1_t vals = __riscv_vfrdiv_vf_f64m1(root, 1.0, vl);

                vfloat64m1_t init = __riscv_vfmv_s_f_f64m1((double)sumx, vl);
                vfloat64m1_t red = __riscv_vfredosum_vs_f64m1_f64m1(vals, init, vl);
                sumx = (real_t)__riscv_vfmv_f_s_f64m1_f64(red);

                i += (Index_type)vl;
            }
        }

        acc += sumx;
        dummy(NULL, NULL, NULL, NULL, NULL, sumx);
    }
#else
    for (int nl = 0; nl < iterations; nl++) {
        real_t sumx = (real_t)0.0;

        Index_type i = 0;
        const Index_type n_unroll = LEN_1D & ~(Index_type)7;
        for (; i < n_unroll; i += 8) {
            real_t xv0 = x0 + (real_t)(i + 0) * h;
            real_t xv1 = x0 + (real_t)(i + 1) * h;
            real_t xv2 = x0 + (real_t)(i + 2) * h;
            real_t xv3 = x0 + (real_t)(i + 3) * h;
            real_t xv4 = x0 + (real_t)(i + 4) * h;
            real_t xv5 = x0 + (real_t)(i + 5) * h;
            real_t xv6 = x0 + (real_t)(i + 6) * h;
            real_t xv7 = x0 + (real_t)(i + 7) * h;

            real_t d0 = xv0 - half;
            real_t d1 = xv1 - half;
            real_t d2 = xv2 - half;
            real_t d3 = xv3 - half;
            real_t d4 = xv4 - half;
            real_t d5 = xv5 - half;
            real_t d6 = xv6 - half;
            real_t d7 = xv7 - half;

            real_t denom0 = d0 * d0 + dy2;
            real_t denom1 = d1 * d1 + dy2;
            real_t denom2 = d2 * d2 + dy2;
            real_t denom3 = d3 * d3 + dy2;
            real_t denom4 = d4 * d4 + dy2;
            real_t denom5 = d5 * d5 + dy2;
            real_t denom6 = d6 * d6 + dy2;
            real_t denom7 = d7 * d7 + dy2;

            sumx += (real_t)1.0 / (real_t)sqrt((double)(denom0 + (real_t)1.0));
            sumx += (real_t)1.0 / (real_t)sqrt((double)(denom1 + (real_t)1.0));
            sumx += (real_t)1.0 / (real_t)sqrt((double)(denom2 + (real_t)1.0));
            sumx += (real_t)1.0 / (real_t)sqrt((double)(denom3 + (real_t)1.0));
            sumx += (real_t)1.0 / (real_t)sqrt((double)(denom4 + (real_t)1.0));
            sumx += (real_t)1.0 / (real_t)sqrt((double)(denom5 + (real_t)1.0));
            sumx += (real_t)1.0 / (real_t)sqrt((double)(denom6 + (real_t)1.0));
            sumx += (real_t)1.0 / (real_t)sqrt((double)(denom7 + (real_t)1.0));
        }

        for (; i < LEN_1D; ++i) {
            real_t xv = x0 + (real_t)i * h;
            real_t d = xv - half;
            real_t denom = d * d + dy2;
            sumx += (real_t)1.0 / (real_t)sqrt((double)(denom + (real_t)1.0));
        }

        acc += sumx;
        dummy(NULL, NULL, NULL, NULL, NULL, sumx);
    }
#endif

    x[0] = acc;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

