                vfloat64m1_t vy   = __riscv_vle64_v_f64m1((const double *)(y + i), vl);
                vfloat64m1_t vz10 = __riscv_vle64_v_f64m1((const double *)(z + i + 10), vl);
                vfloat64m1_t vz11 = __riscv_vle64_v_f64m1((const double *)(z + i + 11), vl);
                vfloat64m1_t tmp  = __riscv_vfmul_vf_f64m1(vz10, (double)r, vl);
                tmp = __riscv_vfadd_vv_f64m1(tmp, __riscv_vfmul_vf_f64m1(vz11, (double)t, vl), vl);
                tmp = __riscv_vfmul_vv_f64m1(tmp, vy, vl);
                tmp = __riscv_vfadd_vf_f64m1(tmp, (double)q, vl);
                __riscv_vse64_v_f64m1((double *)(x + i), tmp, vl);
                i += (Index_type)vl;
            }
#      else
            for (; i < n; ) {
                size_t vl = __riscv_vsetvl_e32m1((size_t)(n - i));
                vfloat32m1_t vy   = __riscv_vle32_v_f32m1((const float *)(y + i), vl);
                vfloat32m1_t vz10 = __riscv_vle32_v_f32m1((const float *)(z + i + 10), vl);
                vfloat32m1_t vz11 = __riscv_vle32_v_f32m1((const float *)(z + i + 11), vl);
                vfloat32m1_t tmp  = __riscv_vfmul_vf_f32m1(vz10, (float)r, vl);
                tmp = __riscv_vfadd_vv_f32m1(tmp, __riscv_vfmul_vf_f32m1(vz11, (float)t, vl), vl);
                tmp = __riscv_vfmul_vv_f32m1(tmp, vy, vl);
                tmp = __riscv_vfadd_vf_f32m1(tmp, (float)q, vl);
