real_t lcals_hydro_2d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t s = 0.0001, t = 0.5;
    Index_type kn = LEN_2D, jn = LEN_2D;

#if defined(__riscv_vector)
    const size_t n_inner = (size_t)(jn - 2);

    for (int nl = 0; nl < iterations / 32 + 1; nl++) {

        for (Index_type k = 1; k < kn - 1; ++k) {
            size_t off = 0;
            while (off < n_inner) {
                size_t vl = __riscv_vsetvl_e32m1(n_inner - off);
                Index_type j = (Index_type)(off + 1);

                vfloat32m1_t zp_kp1_jm1 = __riscv_vle32_v_f32m1(&zp[k+1][j-1], vl);
                vfloat32m1_t zq_kp1_jm1 = __riscv_vle32_v_f32m1(&zq[k+1][j-1], vl);
                vfloat32m1_t zp_k_jm1   = __riscv_vle32_v_f32m1(&zp[k][j-1],   vl);
                vfloat32m1_t zq_k_jm1   = __riscv_vle32_v_f32m1(&zq[k][j-1],   vl);
                vfloat32m1_t zr_k_j     = __riscv_vle32_v_f32m1(&zr[k][j],     vl);
                vfloat32m1_t zr_k_jm1   = __riscv_vle32_v_f32m1(&zr[k][j-1],   vl);
                vfloat32m1_t zm_k_jm1   = __riscv_vle32_v_f32m1(&zm[k][j-1],   vl);
                vfloat32m1_t zm_kp1_jm1 = __riscv_vle32_v_f32m1(&zm[k+1][j-1], vl);

                vfloat32m1_t a_num = __riscv_vfadd_vv_f32m1(zp_kp1_jm1, zq_kp1_jm1, vl);
                a_num = __riscv_vfsub_vv_f32m1(a_num, zp_k_jm1, vl);
                a_num = __riscv_vfsub_vv_f32m1(a_num, zq_k_jm1, vl);
                vfloat32m1_t a_zr  = __riscv_vfadd_vv_f32m1(zr_k_j, zr_k_jm1, vl);
                vfloat32m1_t a_den = __riscv_vfadd_vv_f32m1(zm_k_jm1, zm_kp1_jm1, vl);
                vfloat32m1_t a_val = __riscv_vfdiv_vv_f32m1(__riscv_vfmul_vv_f32m1(a_num, a_zr, vl), a_den, vl);
                __riscv_vse32_v_f32m1(&za[k][j], a_val, vl);

                vfloat32m1_t zp_k_j   = __riscv_vle32_v_f32m1(&zp[k][j],   vl);
                vfloat32m1_t zq_k_j   = __riscv_vle32_v_f32m1(&zq[k][j],   vl);
                vfloat32m1_t zr_km1_j = __riscv_vle32_v_f32m1(&zr[k-1][j], vl);
                vfloat32m1_t zm_k_j   = __riscv_vle32_v_f32m1(&zm[k][j],   vl);

                vfloat32m1_t b_num = __riscv_vfadd_vv_f32m1(zp_k_jm1, zq_k_jm1, vl);
                b_num = __riscv_vfsub_vv_f32m1(b_num, zp_k_j, vl);
                b_num = __riscv_vfsub_vv_f32m1(b_num, zq_k_j, vl);
                vfloat32m1_t b_zr  = __riscv_vfadd_vv_f32m1(zr_k_j, zr_km1_j, vl);
                vfloat32m1_t b_den = __riscv_vfadd_vv_f32m1(zm_k_j, zm_k_jm1, vl);
                vfloat32m1_t b_val = __riscv_vfdiv_vv_f32m1(__riscv_vfmul_vv_f32m1(b_num, b_zr, vl), b_den, vl);
                __riscv_vse32_v_f32m1(&zb[k][j], b_val, vl);

                off += vl;
            }
        }

        for (Index_type k = 1; k < kn - 1; ++k) {
            size_t off = 0;
            while (off < n_inner) {
                size_t vl = __riscv_vsetvl_e32m1(n_inner - off);
                Index_type j = (Index_type)(off + 1);

                vfloat32m1_t za_k_j    = __riscv_vle32_v_f32m1(&za[k][j],    vl);
                vfloat32m1_t za_k_jm1  = __riscv_vle32_v_f32m1(&za[k][j-1],  vl);
                vfloat32m1_t zb_k_j    = __riscv_vle32_v_f32m1(&zb[k][j],    vl);
                vfloat32m1_t zb_kp1_j  = __riscv_vle32_v_f32m1(&zb[k+1][j],  vl);

                vfloat32m1_t zz_k_j    = __riscv_vle32_v_f32m1(&zz[k][j],    vl);
                vfloat32m1_t zz_k_jp1  = __riscv_vle32_v_f32m1(&zz[k][j+1],  vl);
                vfloat32m1_t zz_k_jm1  = __riscv_vle32_v_f32m1(&zz[k][j-1],  vl);
                vfloat32m1_t zz_km1_j  = __riscv_vle32_v_f32m1(&zz[k-1][j],  vl);
                vfloat32m1_t zz_kp1_j  = __riscv_vle32_v_f32m1(&zz[k+1][j],  vl);

                vfloat32m1_t dz1 = __riscv_vfsub_vv_f32m1(zz_k_j, zz_k_jp1, vl);
                vfloat32m1_t dz2 = __riscv_vfsub_vv_f32m1(zz_k_j, zz_k_jm1, vl);
                vfloat32m1_t dz3 = __riscv_vfsub_vv_f32m1(zz_k_j, zz_km1_j, vl);
                vfloat32m1_t dz4 = __riscv_vfsub_vv_f32m1(zz_k_j, zz_kp1_j, vl);

                vfloat32m1_t term = __riscv_vfmul_vv_f32m1(za_k_j, dz1, vl);
                term = __riscv_vfsub_vv_f32m1(term, __riscv_vfmul_vv_f32m1(za_k_jm1, dz2, vl), vl);
                term = __riscv_vfsub_vv_f32m1(term, __riscv_vfmul_vv_f32m1(zb_k_j, dz3, vl), vl);
                term = __riscv_vfadd_vv_f32m1(term, __riscv_vfmul_vv_f32m1(zb_kp1_j, dz4, vl), vl);

                vfloat32m1_t zu_old = __riscv_vle32_v_f32m1(&zu[k][j], vl);
                vfloat32m1_t zu_new = __riscv_vfadd_vv_f32m1(zu_old, __riscv_vfmul_vv_f32m1(__riscv_vfmv_v_f_f32m1(s, vl), term, vl), vl);
                __riscv_vse32_v_f32m1(&zu[k][j], zu_new, vl);

                vfloat32m1_t zr_k_j    = __riscv_vle32_v_f32m1(&zr[k][j],    vl);
                vfloat32m1_t zr_k_jp1  = __riscv_vle32_v_f32m1(&zr[k][j+1],  vl);
                vfloat32m1_t zr_k_jm1  = __riscv_vle32_v_f32m1(&zr[k][j-1],  vl);
                vfloat32m1_t zr_km1_j  = __riscv_vle32_v_f32m1(&zr[k-1][j],  vl);
                vfloat32m1_t zr_kp1_j  = __riscv_vle32_v_f32m1(&zr[k+1][j],  vl);

                dz1 = __riscv_vfsub_vv_f32m1(zr_k_j, zr_k_jp1, vl);
                dz2 = __riscv_vfsub_vv_f32m1(zr_k_j, zr_k_jm1, vl);
                dz3 = __riscv_vfsub_vv_f32m1(zr_k_j, zr_km1_j, vl);
                dz4 = __riscv_vfsub_vv_f32m1(zr_k_j, zr_kp1_j, vl);

                term = __riscv_vfmul_vv_f32m1(za_k_j, dz1, vl);
                term = __riscv_vfsub_vv_f32m1(term, __riscv_vfmul_vv_f32m1(za_k_jm1, dz2, vl), vl);
                term = __riscv_vfsub_vv_f32m1(term, __riscv_vfmul_vv_f32m1(zb_k_j, dz3, vl), vl);
                term = __riscv_vfadd_vv_f32m1(term, __riscv_vfmul_vv_f32m1(zb_kp1_j, dz4, vl), vl);

                vfloat32m1_t zv_old = __riscv_vle32_v_f32m1(&zv[k][j], vl);
                vfloat32m1_t zv_new = __riscv_vfadd_vv_f32m1(zv_old, __riscv_vfmul_vv_f32m1(__riscv_vfmv_v_f_f32m1(s, vl), term, vl), vl);
                __riscv_vse32_v_f32m1(&zv[k][j], zv_new, vl);

                off += vl;
            }
        }

        for (Index_type k = 1; k < kn - 1; ++k) {
            size_t off = 0;
            while (off < n_inner) {
                size_t vl = __riscv_vsetvl_e32m1(n_inner - off);
                Index_type j = (Index_type)(off + 1);

                vfloat32m1_t zr_v = __riscv_vle32_v_f32m1(&zr[k][j], vl);
                vfloat32m1_t zu_v = __riscv_vle32_v_f32m1(&zu[k][j], vl);
                vfloat32m1_t zz_v = __riscv_vle32_v_f32m1(&zz[k][j], vl);
                vfloat32m1_t zv_v = __riscv_vle32_v_f32m1(&zv[k][j], vl);

                vfloat32m1_t zrout_v = __riscv_vfadd_vv_f32m1(zr_v, __riscv_vfmul_vv_f32m1(__riscv_vfmv_v_f_f32m1(t, vl), zu_v, vl), vl);
                vfloat32m1_t zzout_v = __riscv_vfadd_vv_f32m1(zz_v, __riscv_vfmul_vv_f32m1(__riscv_vfmv_v_f_f32m1(t, vl), zv_v, vl), vl);

                __riscv_vse32_v_f32m1(&zrout[k][j], zrout_v, vl);
                __riscv_vse32_v_f32m1(&zzout[k][j], zzout_v, vl);

                off += vl;
            }
        }

        dummy(NULL, NULL, NULL, NULL, NULL, t);
    }
#else
    for (int nl = 0; nl < iterations / 32 + 1; nl++) {
        for (Index_type k = 1; k < kn - 1; ++k) {
            for (Index_type j = 1; j < jn - 1; ++j) {
                za[k][j] = ( zp[k+1][j-1] + zq[k+1][j-1] - zp[k][j-1] - zq[k][j-1] ) *
                           ( zr[k][j] + zr[k][j-1] ) / ( zm[k][j-1] + zm[k+1][j-1] );
                zb[k][j] = ( zp[k][j-1] + zq[k][j-1] - zp[k][j] - zq[k][j] ) *
                           ( zr[k][j] + zr[k-1][j] ) / ( zm[k][j] + zm[k][j-1] );
            }
