real_t lcals_int_predict(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type offset = LEN_1D;
    real_t dm22 = 0.7, dm23 = 0.6, dm24 = 0.5, dm25 = 0.4;
    real_t dm26 = 0.3, dm27 = 0.2, dm28 = 0.1, c0 = 1.0/3.0;

    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector) && defined(REAL_TYPE_IS_DOUBLE)
        {
            Index_type i = 0;

            real_t *p0  = px;
            real_t *p2  = px + offset *  2;
            real_t *p4  = px + offset *  4;
            real_t *p5  = px + offset *  5;
            real_t *p6  = px + offset *  6;
            real_t *p7  = px + offset *  7;
            real_t *p8  = px + offset *  8;
            real_t *p9  = px + offset *  9;
            real_t *p10 = px + offset * 10;
            real_t *p11 = px + offset * 11;
            real_t *p12 = px + offset * 12;

            for (; i < LEN_1D; ) {
                size_t vl = __riscv_vsetvl_e64m4((size_t)(LEN_1D - i));

                vfloat64m4_t acc = __riscv_vfmul_vf_f64m4(
                    __riscv_vle64_v_f64m4((const double *)(p12 + i), vl),
                    (double)dm28, vl);

                vfloat64m4_t tmp = __riscv_vfmul_vf_f64m4(
                    __riscv_vle64_v_f64m4((const double *)(p11 + i), vl),
                    (double)dm27, vl);
                acc = __riscv_vfadd_vv_f64m4(acc, tmp, vl);

                tmp = __riscv_vfmul_vf_f64m4(
                    __riscv_vle64_v_f64m4((const double *)(p10 + i), vl),
                    (double)dm26, vl);
                acc = __riscv_vfadd_vv_f64m4(acc, tmp, vl);

                tmp = __riscv_vfmul_vf_f64m4(
                    __riscv_vle64_v_f64m4((const double *)(p9 + i), vl),
                    (double)dm25, vl);
                acc = __riscv_vfadd_vv_f64m4(acc, tmp, vl);

                tmp = __riscv_vfmul_vf_f64m4(
                    __riscv_vle64_v_f64m4((const double *)(p8 + i), vl),
                    (double)dm24, vl);
                acc = __riscv_vfadd_vv_f64m4(acc, tmp, vl);

                tmp = __riscv_vfmul_vf_f64m4(
                    __riscv_vle64_v_f64m4((const double *)(p7 + i), vl),
                    (double)dm23, vl);
                acc = __riscv_vfadd_vv_f64m4(acc, tmp, vl);

                tmp = __riscv_vfmul_vf_f64m4(
                    __riscv_vle64_v_f64m4((const double *)(p6 + i), vl),
                    (double)dm22, vl);
                acc = __riscv_vfadd_vv_f64m4(acc, tmp, vl);

                tmp = __riscv_vfadd_vv_f64m4(
                    __riscv_vle64_v_f64m4((const double *)(p4 + i), vl),
                    __riscv_vle64_v_f64m4((const double *)(p5 + i), vl),
                    vl);
                tmp = __riscv_vfmul_vf_f64m4(tmp, (double)c0, vl);
                acc = __riscv_vfadd_vv_f64m4(acc, tmp, vl);

                acc = __riscv_vfadd_vv_f64m4(acc,
                    __riscv_vle64_v_f64m4((const double *)(p2 + i), vl), vl);

                __riscv_vse64_v_f64m4((double *)(p0 + i), acc, vl);
                i += (Index_type)vl;
            }
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            px[i] = dm28*px[i + offset * 12] + dm27*px[i + offset * 11] +
                    dm26*px[i + offset * 10] + dm25*px[i + offset *  9] +
                    dm24*px[i + offset *  8] + dm23*px[i + offset *  7] +
                    dm22*px[i + offset *  6] +
                    c0*( px[i + offset *  4] + px[i + offset *  5] ) +
                    px[i + offset *  2];
        }
#endif
        dummy(px, NULL, NULL, NULL, NULL, c0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

