#  if defined(__has_include)
#    if __has_include(<riscv_vector.h>)
#      include <riscv_vector.h>
#      define LCALS_PLANCKIAN_HAVE_RVV 1
#    endif
#  endif
#endif

real_t lcals_planckian(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

#if defined(LCALS_PLANCKIAN_HAVE_RVV)
    if (sizeof(real_t) == sizeof(float)) {
        float *yp = (float *)y;
        float *wp = (float *)w;
        const float *up = (const float *)u;
        const float *vp = (const float *)v;
        const float *xp = (const float *)x;
        float denom_buf[256];

        for (int nl = 0; nl < iterations; nl++) {
            Index_type i = 0;

            while (i < LEN_1D) {
                size_t n = (size_t)(LEN_1D - i);
                if (n > 256) {
                    n = 256;
                }

                size_t vl = __riscv_vsetvl_e32m4(n);

                vfloat32m4_t vu = __riscv_vle32_v_f32m4(up + i, vl);
                vfloat32m4_t vv = __riscv_vle32_v_f32m4(vp + i, vl);
                vfloat32m4_t vy = __riscv_vfdiv_vv_f32m4(vu, vv, vl);
                __riscv_vse32_v_f32m4(yp + i, vy, vl);

                size_t j = 0;
                for (; j + 3 < vl; j += 4) {
                    denom_buf[j]     = expf(yp[i + (Index_type)j])     - 1.0f;
                    denom_buf[j + 1] = expf(yp[i + (Index_type)j + 1]) - 1.0f;
                    denom_buf[j + 2] = expf(yp[i + (Index_type)j + 2]) - 1.0f;
                    denom_buf[j + 3] = expf(yp[i + (Index_type)j + 3]) - 1.0f;
                }
                for (; j < vl; ++j) {
                    denom_buf[j] = expf(yp[i + (Index_type)j]) - 1.0f;
                }

                vfloat32m4_t vx = __riscv_vle32_v_f32m4(xp + i, vl);
                vfloat32m4_t vd = __riscv_vle32_v_f32m4(denom_buf, vl);
                vfloat32m4_t vw = __riscv_vfdiv_vv_f32m4(vx, vd, vl);
                __riscv_vse32_v_f32m4(wp + i, vw, vl);

                i += (Index_type)vl;
            }

            dummy(y, w, u, v, x, 0.0);
        }
    } else
#endif
    {
        for (int nl = 0; nl < iterations; nl++) {
            Index_type i = 0;

            for (; i + 3 < LEN_1D; i += 4) {
                y[i]     = u[i]     / v[i];
                y[i + 1] = u[i + 1] / v[i + 1];
                y[i + 2] = u[i + 2] / v[i + 2];
                y[i + 3] = u[i + 3] / v[i + 3];

                w[i]     = x[i]     / ( expf(y[i])     - 1.0f );
                w[i + 1] = x[i + 1] / ( expf(y[i + 1]) - 1.0f );
                w[i + 2] = x[i + 2] / ( expf(y[i + 2]) - 1.0f );
                w[i + 3] = x[i + 3] / ( expf(y[i + 3]) - 1.0f );
            }

            for (; i < LEN_1D; ++i) {
                y[i] = u[i] / v[i];
                w[i] = x[i] / ( expf(y[i]) - 1.0f );
            }

            dummy(y, w, u, v, x, 0.0);
        }
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

real_t lcals_tridiag_elim(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        if (sizeof(real_t) == 8) {
            size_t n = (LEN_1D > 1) ? (size_t)(LEN_1D - 1) : 0;
            real_t *pxout = &xout[1];
            const real_t *pz = &z[1];
            const real_t *py = &y[1];
            const real_t *pxin = &xin[0];

            if (n != 0) {
                __asm__ volatile (
                    "1:\n\t"
                    "vsetvli t0, %[n], e64, m1, ta, ma\n\t"
                    "slli    t1, t0, 3\n\t"
                    "vle64.v v0, (%[pz])\n\t"
                    "vle64.v v1, (%[py])\n\t"
                    "vle64.v v2, (%[pxin])\n\t"
                    "vfsub.vv v1, v1, v2\n\t"
                    "vfmul.vv v0, v0, v1\n\t"
                    "vse64.v v0, (%[pxout])\n\t"
                    "add     %[pz], %[pz], t1\n\t"
                    "add     %[py], %[py], t1\n\t"
                    "add     %[pxin], %[pxin], t1\n\t"
                    "add     %[pxout], %[pxout], t1\n\t"
                    "sub     %[n], %[n], t0\n\t"
                    "bnez    %[n], 1b\n\t"
                    : [n] "+r" (n),
                      [pz] "+r" (pz),
                      [py] "+r" (py),
                      [pxin] "+r" (pxin),
                      [pxout] "+r" (pxout)
                    :
                    : "t0", "t1", "memory"
                );
            }
        } else if (sizeof(real_t) == 4) {
            size_t n = (LEN_1D > 1) ? (size_t)(LEN_1D - 1) : 0;
            real_t *pxout = &xout[1];
            const real_t *pz = &z[1];
            const real_t *py = &y[1];
            const real_t *pxin = &xin[0];

            if (n != 0) {
                __asm__ volatile (
                    "1:\n\t"
                    "vsetvli t0, %[n], e32, m1, ta, ma\n\t"
                    "slli    t1, t0, 2\n\t"
                    "vle32.v v0, (%[pz])\n\t"
                    "vle32.v v1, (%[py])\n\t"
                    "vle32.v v2, (%[pxin])\n\t"
                    "vfsub.vv v1, v1, v2\n\t"
                    "vfmul.vv v0, v0, v1\n\t"
                    "vse32.v v0, (%[pxout])\n\t"
                    "add     %[pz], %[pz], t1\n\t"
                    "add     %[py], %[py], t1\n\t"
                    "add     %[pxin], %[pxin], t1\n\t"
                    "add     %[pxout], %[pxout], t1\n\t"
                    "sub     %[n], %[n], t0\n\t"
                    "bnez    %[n], 1b\n\t"
                    : [n] "+r" (n),
                      [pz] "+r" (pz),
                      [py] "+r" (py),
                      [pxin] "+r" (pxin),
                      [pxout] "+r" (pxout)
                    :
                    : "t0", "t1", "memory"
                );
            }
        } else
#endif
        {
            Index_type i = 1;
            for (; i + 3 < LEN_1D; i += 4) {
                xout[i]     = z[i]     * ( y[i]     - xin[i-1] );
                xout[i + 1] = z[i + 1] * ( y[i + 1] - xin[i] );
                xout[i + 2] = z[i + 2] * ( y[i + 2] - xin[i + 1] );
                xout[i + 3] = z[i + 3] * ( y[i + 3] - xin[i + 2] );
            }
            for (; i < LEN_1D; ++i) {
                xout[i] = z[i] * ( y[i] - xin[i-1] );
            }
        }

        dummy(xout, xin, y, z, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

