real_t stream_dot(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t dot_acc = 0.0;
    for (int nl = 0; nl < iterations; nl++) {
        real_t local = 0.0;
        for (Index_type i = 0; i < LEN_1D; ++i) {
            local += a[i] * b[i];
        }
        dot_acc += local;
        dummy(a, b, NULL, NULL, NULL, local);
    }
    x[0] = dot_acc;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

real_t stream_mul(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const real_t alpha = (real_t)0.42;
    real_t * restrict pb = b;
    const real_t * restrict pc = c;

    for (int nl = 0; nl < iterations; nl++) {
        Index_type i = 0;

#if defined(__GNUC__) || defined(__clang__)
#pragma GCC ivdep
#endif
        for (; i + 7 < LEN_1D; i += 8) {
            pb[i + 0] = alpha * pc[i + 0];
            pb[i + 1] = alpha * pc[i + 1];
            pb[i + 2] = alpha * pc[i + 2];
            pb[i + 3] = alpha * pc[i + 3];
            pb[i + 4] = alpha * pc[i + 4];
            pb[i + 5] = alpha * pc[i + 5];
            pb[i + 6] = alpha * pc[i + 6];
            pb[i + 7] = alpha * pc[i + 7];
        }

        for (; i < LEN_1D; ++i) {
            pb[i] = alpha * pc[i];
        }

        dummy(b, c, NULL, NULL, NULL, alpha);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

real_t stream_triad(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t alpha = 0.42;
    for (int nl = 0; nl < iterations; nl++) {
        for (Index_type i = 0; i < LEN_1D; ++i) {
            a[i] = b[i] + alpha * c[i];
        }
        dummy(a, b, c, NULL, NULL, alpha);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}
